from pathlib import Path
pins=[]
for line in Path('terminal/server/requirements.txt').read_text().splitlines():
 if not line:continue
 name,version=line.split('==');assert re.fullmatch(r'[A-Za-z0-9_.-]+',name)and re.fullmatch(r'[A-Za-z0-9_.+-]+',version);pins.append((name,version))
results=[];total=0
with httpx.Client(timeout=8,follow_redirects=False,headers={'Accept-Encoding':'identity','User-Agent':'GIG-ATLAS-public-dependency-metadata-review'})as client:
 for name,version in pins:
  url=f'https://pypi.org/pypi/{name}/{version}/json'
  try:
   with client.stream('GET',url)as response:
    if response.status_code!=200:raise ValueError('metadata_http_'+str(response.status_code))
    raw=bytearray()
    for chunk in response.iter_bytes():
     if len(raw)+len(chunk)>2097152 or total+len(chunk)>8388608:raise ValueError('metadata_body_budget')
     raw.extend(chunk);total+=len(chunk)
   d=json.loads(raw);v=d['vulnerabilities'];assert isinstance(v,list)
   results.append({'package':name,'version':version,'reported_version':d['info']['version'],'vulnerabilities':v,'bytes':len(raw),'response_sha256':hashlib.sha256(raw).hexdigest()})
  except Exception as error:
   results.append({'package':name,'version':version,'status':'UNVERIFIED_METADATA_FETCH','error_type':type(error).__name__});break
  time.sleep(.1)
r={'schema':'gig.atlas.pypi_metadata_advisory.v1','source':'official PyPI per-version JSON vulnerabilities metadata','results':results,'requested_pin_count':len(pins),'completed':len(results)==len(pins)and all('vulnerabilities'in r for r in results),'total_body_bytes':total,'known_advisory_count':sum(len(r.get('vulnerabilities',[]))for r in results),'scope':'Direct pinned server requirements only;not full transitive/OS/native dependency or penetration-test certification','retries':0,'provider_data_requests':0}
Path('build/final-master/pypi-advisory.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:v for k,v in r.items()if k!='results'}))
